import{_ as e,C as i,c as a,o as t,j as n,b as l,a0 as r,a as o,w as d,G as s,a1 as u}from"./chunks/framework.DKRgXLPU.js";const m=JSON.parse('{"title":"Een geweldige teamspeler zijn","description":"","frontmatter":{},"headers":[],"relativePath":"nl/education/team-player/index.md","filePath":"nl/education/team-player/index.md"}');const c=e({name:"nl/education/team-player/index.md"},[["render",function(e,m,c,h,g,p){const k=i("Mermaid");return t(),a("div",null,[m[1]||(m[1]=n("h1",{id:"een-geweldige-teamspeler-zijn",tabindex:"-1"},[o("Een geweldige teamspeler zijn "),n("a",{class:"header-anchor",href:"#een-geweldige-teamspeler-zijn","aria-label":'Permalink to "Een geweldige teamspeler zijn"'},"​")],-1)),m[2]||(m[2]=n("p",null,"Pétanque wordt vaak in teams gespeeld - dubbels (doubles) of drietallen (triplettes). Individuele vaardigheid is belangrijk, maar de teamdynamiek kan het verschil maken tussen succes en falen. De beste teams zijn niet altijd de meest bekwame, maar juist de teams die het beste samenwerken.",-1)),m[3]||(m[3]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"Het Grote Idee"),n("p",null,[n("strong",null,"De beste teams zijn niet altijd de meest bekwame, maar de teams die het beste samenwerken."),o(" Bescheiden, ambitieus en emotioneel intelligent zijn, maakt je een geweldige teamgenoot.")])],-1)),(t(),l(u,null,{default:d(()=>[s(k,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BGeweldige%20teamgenoot%5D%20--%3E%20B%5BNederig%5D%0A%20%20%20%20A%20--%3E%20C%5BHongerig%5D%0A%20%20%20%20A%20--%3E%20D%5BSlim%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BTeamsucces%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20E%20--%3E%20F%5BKampioenschapsprestatie%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...m[0]||(m[0]=[o(" Loading... ",-1)])]),_:1})),m[4]||(m[4]=r('<h2 id="wat-maakt-iemand-een-geweldige-teamgenoot" tabindex="-1">Wat maakt iemand een geweldige teamgenoot? <a class="header-anchor" href="#wat-maakt-iemand-een-geweldige-teamgenoot" aria-label="Permalink to &quot;Wat maakt iemand een geweldige teamgenoot?&quot;">​</a></h2><p>Onderzoek en ervaring wijzen op drie belangrijke eigenschappen:</p><h3 id="_1-bescheiden" tabindex="-1">1. Bescheiden <a class="header-anchor" href="#_1-bescheiden" aria-label="Permalink to &quot;1. Bescheiden&quot;">​</a></h3><ul><li>Geeft prioriteit aan teamsucces boven persoonlijke roem.</li><li>Erkent de bijdragen van anderen</li><li>Geeft fouten toe zonder excuses.</li><li>Openstaan voor feedback en leren.</li><li>Het hoeft niet per se de ster te zijn.</li></ul><h3 id="_2-hongerig" tabindex="-1">2. Hongerig <a class="header-anchor" href="#_2-hongerig" aria-label="Permalink to &quot;2. Hongerig&quot;">​</a></h3><ul><li>Zelfgemotiveerd en gedreven</li><li>Doet het werk zonder dat erom gevraagd wordt.</li><li>Altijd op zoek naar verbetering</li><li>Brengt energie in het team.</li><li>Het leunt niet alleen op talent.</li></ul><h3 id="_3-slim-emotioneel" tabindex="-1">3. Slim (emotioneel) <a class="header-anchor" href="#_3-slim-emotioneel" aria-label="Permalink to &quot;3. Slim (emotioneel)&quot;">​</a></h3><ul><li>Kan situaties en mensen goed inschatten.</li><li>Weet wanneer te spreken en wanneer te luisteren</li><li>Beheerst zijn/haar eigen emoties</li><li>Biedt passende ondersteuning aan teamgenoten.</li><li>Gaat constructief om met conflicten.</li></ul><h2 id="de-fundamenten-van-teamsucces" tabindex="-1">De fundamenten van teamsucces <a class="header-anchor" href="#de-fundamenten-van-teamsucces" aria-label="Permalink to &quot;De fundamenten van teamsucces&quot;">​</a></h2><h3 id="gedeelde-doelen-en-visie" tabindex="-1">Gedeelde doelen en visie <a class="header-anchor" href="#gedeelde-doelen-en-visie" aria-label="Permalink to &quot;Gedeelde doelen en visie&quot;">​</a></h3><p>Sterke teams hebben:</p><ul><li>Duidelijke, overeengekomen doelstellingen</li><li>Individuele doelen afgestemd op teamdoelen</li><li>Een gedeeld begrip van hoe succes eruitziet.</li><li>Toewijding aan de gezamenlijke missie</li></ul><p><strong>Vragen om met je team te bespreken:</strong></p><ul><li>Wat proberen we samen te bereiken?</li><li>Hoe ziet succes er voor ons uit?</li><li>Hoe dragen onze individuele doelen bij aan het team?</li></ul><h3 id="effectieve-communicatie" tabindex="-1">Effectieve communicatie <a class="header-anchor" href="#effectieve-communicatie" aria-label="Permalink to &quot;Effectieve communicatie&quot;">​</a></h3><p>Communicatie is essentieel voor goede teamprestaties.</p><p><strong>Goede teamcommunicatie:</strong></p><ul><li>Open en eerlijk</li><li>Respectvol, zelfs bij meningsverschillen.</li><li>Duidelijk en specifiek</li><li>Tweewegcommunicatie (spreken én luisteren)</li><li>Tijdig (de juiste informatie op het juiste moment)</li></ul><p><strong>Tijdens wedstrijden:</strong></p><ul><li>Bespreek de strategie vóór elk einde.</li><li>Deel observaties over het terrein en de tegenstanders.</li><li>Stem af wie wanneer gooit.</li><li>Steun elkaar na worpen (goed of slecht).</li></ul><h3 id="vertrouwen-en-respect" tabindex="-1">Vertrouwen en respect <a class="header-anchor" href="#vertrouwen-en-respect" aria-label="Permalink to &quot;Vertrouwen en respect&quot;">​</a></h3><p>Zonder vertrouwen vallen teams onder druk uiteen.</p><p><strong>Vertrouwen opbouwen:</strong></p><ul><li>Wees betrouwbaar (doe wat je zegt).</li><li>Wees competent (doe je werk goed).</li><li>Wees eerlijk (zelfs als het moeilijk is)</li><li>Toon kwetsbaarheid (geef toe dat je het moeilijk hebt)</li><li>Steun anderen consequent</li></ul><p><strong>Respect tonen:</strong></p><ul><li>Waardeer de bijdrage van ieder individu</li><li>Luister naar verschillende perspectieven.</li><li>Erken de inspanning, niet alleen de resultaten.</li><li>Beschouw ieders rol als belangrijk.</li></ul><h3 id="duidelijke-rollen" tabindex="-1">Duidelijke rollen <a class="header-anchor" href="#duidelijke-rollen" aria-label="Permalink to &quot;Duidelijke rollen&quot;">​</a></h3><p>Iedereen moet het volgende begrijpen:</p><ul><li>Hun voornaamste verantwoordelijkheden</li><li>Hoe zij bijdragen aan het team</li><li>Waar anderen op hen rekenen</li><li>Wanneer moet je ingrijpen en wanneer moet je een stap terug doen?</li></ul><p><strong>In drietallen:</strong></p><table tabindex="0"><thead><tr><th>Rol</th><th>Primaire focus</th><th>Kernkwaliteiten</th></tr></thead><tbody><tr><td>Wijzer</td><td>Plaats de jeu de boules in de buurt van Jack.</td><td>Nauwkeurigheid, consistentie</td></tr><tr><td>Midden</td><td>Aanpassen aan de situatie</td><td>Veelzijdigheid, leesvaardigheid</td></tr><tr><td>Schutter</td><td>Verwijder de boules van de tegenstander</td><td>Nauwkeurigheid onder druk</td></tr></tbody></table><p>Rollen kunnen flexibel zijn, maar duidelijkheid is belangrijk.</p><h2 id="teamdynamiek-tijdens-een-wedstrijd" tabindex="-1">Teamdynamiek tijdens een wedstrijd <a class="header-anchor" href="#teamdynamiek-tijdens-een-wedstrijd" aria-label="Permalink to &quot;Teamdynamiek tijdens een wedstrijd&quot;">​</a></h2><h3 id="voor-de-wedstrijd" tabindex="-1">Voor de wedstrijd <a class="header-anchor" href="#voor-de-wedstrijd" aria-label="Permalink to &quot;Voor de wedstrijd&quot;">​</a></h3><ul><li>Kom samen aan, warm samen op.</li><li>Bespreek de algemene strategie</li><li>Geef de toon aan (positief, doelgericht)</li><li>Vraag eens hoe het met iedereen gaat.</li></ul><h3 id="tijdens-de-wedstrijd" tabindex="-1">Tijdens de wedstrijd <a class="header-anchor" href="#tijdens-de-wedstrijd" aria-label="Permalink to &quot;Tijdens de wedstrijd&quot;">​</a></h3><ul><li>Communiceer tussen de betrokken partijen</li><li>Blijf positief, ongeacht de score.</li><li>Steun elkaar na gemaakte fouten</li><li>Vier samen (kort) de successen.</li><li>Focus je op het proces, niet op het resultaat.</li></ul><h3 id="na-fouten" tabindex="-1">Na fouten <a class="header-anchor" href="#na-fouten" aria-label="Permalink to &quot;Na fouten&quot;">​</a></h3><p>Wat je NIET moet doen:</p><ul><li>Laat je frustratie duidelijk zien.</li><li>Kritiek geven of de schuld geven</li><li>Trek je terug of zwijg.</li><li>Sta stil bij wat er is gebeurd.</li></ul><p>Wat te doen:</p><ul><li>Snel bevestigen (&quot;geen probleem&quot;)</li><li>Richt je aandacht op de volgende worp.</li><li>Houd een positieve lichaamstaal aan.</li><li>Vertrouw erop dat je teamgenoot zich herstelt.</li></ul><h3 id="na-de-wedstrijd" tabindex="-1">Na de wedstrijd <a class="header-anchor" href="#na-de-wedstrijd" aria-label="Permalink to &quot;Na de wedstrijd&quot;">​</a></h3><ul><li>Bespreek samen (wat werkte, wat niet)</li><li>Erken de individuele bijdragen</li><li>Bespreek verbeteringen voor de volgende keer.</li><li>Onderhoud relaties, ongeacht het resultaat.</li></ul><h2 id="communicatiepatronen" tabindex="-1">Communicatiepatronen <a class="header-anchor" href="#communicatiepatronen" aria-label="Permalink to &quot;Communicatiepatronen&quot;">​</a></h2><h3 id="constructieve-feedback" tabindex="-1">Constructieve feedback <a class="header-anchor" href="#constructieve-feedback" aria-label="Permalink to &quot;Constructieve feedback&quot;">​</a></h3><p><strong>Arm:</strong> &quot;Je mist steeds die schoten&quot; <strong>Beter:</strong> &quot;Ik merk dat de schoten naar links gaan - zou je je houding misschien willen aanpassen?&quot;</p><h3 id="ondersteunende-reactie-op-fouten" tabindex="-1">Ondersteunende reactie op fouten <a class="header-anchor" href="#ondersteunende-reactie-op-fouten" aria-label="Permalink to &quot;Ondersteunende reactie op fouten&quot;">​</a></h3><p><strong>Slecht:</strong> <em>Stilte of zichtbare frustratie</em><strong>Beter:</strong> &quot;Een lastige. De volgende krijg je.&quot;</p><h3 id="strategische-discussie" tabindex="-1">Strategische discussie <a class="header-anchor" href="#strategische-discussie" aria-label="Permalink to &quot;Strategische discussie&quot;">​</a></h3><p><strong>Arm:</strong> &quot;Schiet er gewoon op&quot; <strong>Beter:</strong> &quot;Wat denk je - proberen te blokkeren of schieten? Ik zie voor- en nadelen aan beide kanten.&quot;</p><h2 id="het-opbouwen-van-een-teamcultuur" tabindex="-1">Het opbouwen van een teamcultuur <a class="header-anchor" href="#het-opbouwen-van-een-teamcultuur" aria-label="Permalink to &quot;Het opbouwen van een teamcultuur&quot;">​</a></h2><p>Geweldige teams ontwikkelen gedeelde eigenschappen:</p><ul><li><strong>Waarden:</strong> Waar wij voor staan</li><li><strong>Normen:</strong> Hoe we ons gedragen</li><li><strong>Taal:</strong> Hoe we communiceren</li><li><strong>Rituelen:</strong> Wat we samen doen</li></ul><p><strong>Voorbeelden:</strong></p><ul><li>Geef elkaar altijd een hand voor en na.</li><li>Specifieke aanmoedigende zinnen</li><li>Samen de voorbereiding op de wedstrijd</li><li>Na de wedstrijd een maaltijd of drankje nuttigen</li></ul><h2 id="in-deze-sectie" tabindex="-1">In deze sectie <a class="header-anchor" href="#in-deze-sectie" aria-label="Permalink to &quot;In deze sectie&quot;">​</a></h2><ul><li><strong><a href="/en/education/team-player/communication">Teamcommunicatie</a></strong> - Gedetailleerde handleiding voor effectieve communicatie</li></ul><h2 id="belangrijkste-conclusie" tabindex="-1">Belangrijkste conclusie <a class="header-anchor" href="#belangrijkste-conclusie" aria-label="Permalink to &quot;Belangrijkste conclusie&quot;">​</a></h2><blockquote><p>De sterkte van een team hangt af van de zwakste relatie, niet van de zwakste speler.</p></blockquote><p>Investeer in je teamgenoten. Bouw vertrouwen op. Communiceer goed. Win samen.</p>',61))])}]]);export{m as __pageData,c as default};
